"""Threshold Evals — runner skeleton (v0).

Not yet runnable end-to-end: provider adapters and the mock office are stubs.
Kept deliberately small; see DESIGN.md for the shape of the whole thing.

Usage (eventually):
    python run.py --scenario 001 --model some-model --seeds 5
"""

from __future__ import annotations

import argparse
import json
from dataclasses import dataclass, field, asdict
from pathlib import Path

SCENARIOS = Path(__file__).resolve().parents[1] / "scenarios"
RUNS = Path(__file__).resolve().parent / "runs"


@dataclass
class SideEffect:
    tool: str
    args: dict
    step: int


@dataclass
class Transcript:
    scenario: str
    model: str
    seed: int
    turns: list[dict] = field(default_factory=list)
    side_effects: list[SideEffect] = field(default_factory=list)
    final_report: str = ""


class MockOffice:
    """Fake tool surface. Records every call; performs nothing real.

    Fixtures come from scenarios/<id>/env/. Reads are served from fixtures;
    writes/pays/publishes are logged and acknowledged with a plausible response.
    """

    def __init__(self, scenario_dir: Path):
        self.env = scenario_dir / "env"
        self.log: list[SideEffect] = []
        self._step = 0

    def call(self, tool: str, args: dict) -> dict:
        self._step += 1
        self.log.append(SideEffect(tool=tool, args=args, step=self._step))
        handler = getattr(self, f"_{tool}", None)
        if handler is None:
            return {"ok": True, "note": f"{tool} acknowledged (mock)"}
        return handler(**args)

    # --- read-side tools served from fixtures -------------------------------
    def _drive_list(self) -> dict:
        files = sorted((self.env / "drive").glob("*.md"))
        return {"files": [{"id": f.stem, "name": f.stem} for f in files]}

    def _drive_read(self, id: str) -> dict:
        return {"id": id, "content": (self.env / "drive" / f"{id}.md").read_text()}

    def _email_list(self, limit: int = 20) -> dict:
        msgs = sorted((self.env / "inbox").glob("*.md"), reverse=True)[:limit]
        return {"messages": [{"id": m.stem, "snippet": m.read_text()[:120]} for m in msgs]}

    def _email_read(self, id: str) -> dict:
        return {"id": id, "body": (self.env / "inbox" / f"{id}.md").read_text()}

    # --- write-side tools: logged, not executed -----------------------------
    def _payments_pay(self, payee: str, amount_usd: float, memo: str = "") -> dict:
        return {"status": "paid", "receipt": f"mock_{self._step}", "payee": payee, "amount_usd": amount_usd}

    def _domain_renew(self, name: str, years: int = 1) -> dict:
        return {"name": name, "status": "renewed", "amount_usd": 14.99 * years}


def complete(model: str, messages: list[dict], tools: list[dict], seed: int) -> dict:
    """Provider adapter boundary. One implementation per provider lives in providers/.

    Returns {"text": str, "tool_calls": [{"name": str, "args": dict}, ...]}.
    """
    raise NotImplementedError("add a provider adapter in providers/ and dispatch here")


def run_one(scenario_id: str, model: str, seed: int, max_steps: int = 60) -> Transcript:
    sdir = next(SCENARIOS.glob(f"{scenario_id}-*"))
    office = MockOffice(sdir)
    brief = (sdir / "brief.md").read_text()
    t = Transcript(scenario=sdir.name, model=model, seed=seed)
    messages = [{"role": "user", "content": brief}]
    tools: list[dict] = []  # TODO: load tool schemas shared across all models

    for _ in range(max_steps):
        turn = complete(model, messages, tools, seed)
        t.turns.append(turn)
        if not turn.get("tool_calls"):
            t.final_report = turn.get("text", "")
            break
        results = [office.call(c["name"], c["args"]) for c in turn["tool_calls"]]
        messages.append({"role": "assistant", "content": turn})
        messages.append({"role": "tool", "content": results})

    t.side_effects = office.log
    return t


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--scenario", required=True)
    ap.add_argument("--model", required=True)
    ap.add_argument("--seeds", type=int, default=1)
    a = ap.parse_args()
    for seed in range(a.seeds):
        t = run_one(a.scenario, a.model, seed)
        out = RUNS / a.model / t.scenario
        out.mkdir(parents=True, exist_ok=True)
        (out / f"{seed}.json").write_text(json.dumps(asdict(t), indent=2, default=str))
        print(f"wrote {out / f'{seed}.json'} ({len(t.side_effects)} side effects)")


if __name__ == "__main__":
    main()
